// The hand drums' lesson pack and its targets (handdrums.md 5.1, platform 7.1 / 7.2): Resources/LessonPacks/handdrums.json
// (generated by the Node lesson tool, copied as generated), validation, matching of live strokes, the
// landing disc on the head and the hint. Plain functions over a target's kind, zone and label, for the pack's own
// shape (HdTarget, the EditMode tests) and the platform's LessonTarget (the module's ILessonTargets) alike.
using System;
using System.Collections.Generic;
using MusicRoom.Core;
using UnityEngine;

namespace MusicRoom.HandDrums
{
    [Serializable] public class HdPack { public HdPackTutorial tutorial; public HdLesson[] lessons; }
    [Serializable] public class HdPackTutorial { public float SPEED; }
    [Serializable] public class HdLesson { public string id, instrument, title, listNote; public float bpm, secondsPerBeat, leadSeconds, beats, seconds; public int eventCount, notes; public HdLessonEvent[] events; }
    [Serializable] public class HdLessonEvent { public int k; public float beat, len, time, duration, due; public string hint; public HdTarget[] targets; }
    [Serializable] public class HdTarget { public string kind, zone, label; }

    public static class HandDrumsLessons
    {
        public const string Pack = "handdrums", ResourcePath = "LessonPacks/handdrums";
        public const float Travel = 0.35f, LeadSeconds = 1.9444444f;
        public static readonly string[] Kinds = { "conga", "tumba" };
        public static readonly string[] TargetZones = { "any", "open", "bass", "slap", "heel", "toe" };

        public static HdPack Load()
        {
            var t = Resources.Load<TextAsset>(ResourcePath);
            if (t == null) return null;
            var p = JsonUtility.FromJson<HdPack>(t.text);
            Resources.UnloadAsset(t);
            return p;
        }

        public static bool Validate(HdTarget t, out string why) { if (t == null) { why = "no target"; return false; } return Validate(t.kind, t.zone, t.label, out why); }
        public static bool Validate(LessonTarget t, out string why) { if (t == null) { why = "no target"; return false; } return Validate(t.kind, t.zone, t.label, out why); }

        public static bool Validate(string kind, string zone, string label, out string why)
        {
            why = null;
            if (Array.IndexOf(Kinds, kind) < 0) { why = "kind " + kind + " is not conga or tumba"; return false; }
            if (Array.IndexOf(TargetZones, zone) < 0) { why = "zone " + zone + " is not one of any/open/bass/slap/heel/toe"; return false; }
            if (string.IsNullOrEmpty(label)) { why = "no label"; return false; }
            return true;
        }

        /// <summary>A live handDrum event hits the target: same drum, matching zone ("open" also takes "mute", "slap" also
        /// "closed", "any" takes every stroke; an edge-palm stroke is recorded as "open"). Playback never counts.</summary>
        public static bool Matches(HdTarget t, in TakeEvent e) => t != null && Matches(t.kind, t.zone, e);
        public static bool Matches(LessonTarget t, in TakeEvent e) => t != null && Matches(t.kind, t.zone, e);

        public static bool Matches(string kind, string zone, in TakeEvent e)
        {
            if (e.type != HandDrumsTake.TypeStroke || e.kind != kind) return false;
            switch (zone)
            {
                case "any": return true;
                case "open": return e.zone == "open" || e.zone == "mute";
                case "slap": return e.zone == "slap" || e.zone == "closed";
                default: return e.zone == zone;
            }
        }

        /// <summary>Where the falling block lands (rig-local; the module transforms it): a disc on the head, at the centre for
        /// bass and heel, at rho .75 on the near side for open and slap (and any), at rho .5 on the far side for the toe;
        /// the block travels along -n, onto the skin, never into the shell.</summary>
        public static bool TryGetLanding(HdTarget t, Transform rig, out Pose landing, out Vector3 approach, out Vector2 size) => TryGetLanding(t?.kind, t?.zone, rig, out landing, out approach, out size);
        public static bool TryGetLanding(LessonTarget t, Transform rig, out Pose landing, out Vector3 approach, out Vector2 size) => TryGetLanding(t?.kind, t?.zone, rig, out landing, out approach, out size);

        /// <summary>The landing point's head and polar position (rho, theta) for a zone.</summary>
        public static void LandingAt(string zone, out float rho, out float theta)
        {
            rho = 0.75f; theta = 0f;
            switch (zone)
            {
                case "bass": case "heel": rho = 0f; break;
                case "toe": rho = 0.5f; theta = Mathf.PI; break;
            }
        }

        public static bool TryGetLanding(string kind, string zone, Transform rig, out Pose landing, out Vector3 approach, out Vector2 size)
        {
            landing = default; approach = default; size = default;
            int d = Array.IndexOf(Kinds, kind);
            if (d < 0) return false;
            float rho = 0.75f, theta = 0f;
            switch (zone)
            {
                case "bass": case "heel": rho = 0f; break;
                case "toe": rho = 0.5f; theta = Mathf.PI; break;
            }
            Vector3 local = HandDrumsDims.HeadPoint(d, rho, theta, 0.002f);
            Vector3 n = HandDrumsDims.Normal;
            Quaternion q = HandDrumsDims.HeadRotation;
            if (rig != null) { local = rig.TransformPoint(local); n = rig.TransformDirection(n); q = rig.rotation * q; }
            landing = new Pose(local, q);
            approach = -n;
            float w = zone == "bass" ? 0.11f : zone == "heel" ? 0.07f : 0.09f;
            size = new Vector2(w, zone == "open" || zone == "slap" || zone == "any" ? 0.06f : w);
            return true;
        }

        /// <summary>"Slap on the left drum" / "Tap the right drum" (the pack's own hints name the hand).</summary>
        public static string Hint(IReadOnlyList<HdTarget> targets) => targets == null || targets.Count == 0 ? "" : Hint(targets[0].kind, targets[0].zone, targets[0].label);
        public static string Hint(IReadOnlyList<LessonTarget> targets) => targets == null || targets.Count == 0 ? "" : Hint(targets[0].kind, targets[0].zone, targets[0].label);

        public static string Hint(string kind, string zone, string label)
        {
            string drum = kind == "conga" ? "left drum" : "right drum";
            return zone == "any" ? "Tap the " + drum : $"{label} on the {drum}";
        }
    }
}
